import os
from typing import Any, Dict

from openai import OpenAI


def translate_dict_values(data: Dict[str, Any], target_language: str = "Spanish") -> Dict[str, Any]:
    client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))
    model = "gpt-4o-mini"

    translated: Dict[str, Any] = {}

    for key, value in data.items():
        if isinstance(value, str):
            prompt = (
                f"Translate the following text into {target_language}. "
                f"Return only the translation, with no quotes or extra commentary:\n\n{value}"
            )
            response = client.chat.completions.create(
                model=model,
                messages=[
                    {"role": "system", "content": "You are a precise translation engine."},
                    {"role": "user", "content": prompt},
                ],
                temperature=0,
            )
            translated[key] = response.choices[0].message.content.strip()
        else:
            translated[key] = value

    return translated
